			'import * as React from "react";\nimport { AlertTriangleIcon } from "lucide-react";\nimport { Button } from "@workspace/ui/components/button";\nimport { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@workspace/ui/components/dialog";\n\nexport function Dialog7Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="flex items-center justify-center">\n\t\t\t<Dialog>\n\t\t\t\t<DialogTrigger render={<Button variant="outline" />}>Delete Item</DialogTrigger>\n\t\t\t\t<DialogContent>\n\t\t\t\t\t<DialogHeader>\n\t\t\t\t\t\t<div className="flex items-start gap-3">\n\t\t\t\t\t\t\t<div className="flex size-10 shrink-0 items-center justify-center rounded-full bg-destructive/10 text-destructive">\n\t\t\t\t\t\t\t\t<AlertTriangleIcon className="size-5" />\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div className="flex flex-col gap-1">\n\t\t\t\t\t\t\t\t<DialogTitle>Are you sure?</DialogTitle>\n\t\t\t\t\t\t\t\t<DialogDescription>This action cannot be undone. This will permanently delete the item and remove all associated data from our servers.</DialogDescription>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</DialogHeader>\n\t\t\t\t\t<DialogFooter>\n\t\t\t\t\t\t<DialogClose render={<Button variant="outline" />}>Cancel</DialogClose>\n\t\t\t\t\t\t<Button variant="destructive">Delete</Button>\n\t\t\t\t\t</DialogFooter>\n\t\t\t\t</DialogContent>\n\t\t\t</Dialog>\n\t\t</div>\n\t);\n}\n',
